{
  "tasks": [
    {
      "task_id": "T01",
      "title": "本科岗位各城市薪资中位数比较",
      "business_question": "在只看本科岗位的条件下，按城市统计薪资元的中位数是多少？",
      "priority": "P0",
      "priority_reason": "核心需求要求按城市比较本科岗位的薪资中位数。删除此任务将无法回答关于不同城市本科学历薪资水平差异的核心决策问题。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "本科"
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "median",
                "field": "field_0003",
                "alias": "salary_median"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        }
      ]
    }
  ]
}
